function toast(s){$('toast').textContent=s;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3000)}function save(){try{localStorage.setItem(key,JSON.stringify(data));render();window.homeCloud?.changed()}catch{toast('저장 공간이 부족하거나 브라우저 저장을 사용할 수 없어요. 백업을 내보내세요.')}}
function render(){let regions=[...new Set(['동탄','광교','기흥','수원',...data.map(a=>a.region)])],q=$('search').value.trim().toLowerCase(),items=data.filter(a=>(a.name+' '+a.address).toLowerCase().includes(q));$('count').textContent=data.length+'개';$('regioncount').textContent=regions.length+'곳';$('last').textContent=data.length?data.flatMap(a=>a.history.map(h=>h.date)).sort().at(-1).replaceAll('-','.'): '—';let max=Math.max(12,...data.map(a=>Math.ceil(latest(a).price/2)*2)),bands=[];for(let p=4;p<max;p+=2)bands.push([p,p+2]);let board=$('board');board.style.gridTemplateColumns='var(--band-width,110px) repeat('+regions.length+',minmax(var(--region-min,240px),1fr))';board.innerHTML='<div class="head">가격대</div>'+regions.map(r=>'<div class="head">'+esc(r)+' <span style="font-size:14px;color:#8495a3;font-weight:400">'+items.filter(a=>a.region===r).length+'</span></div>').join('')+bands.map(([lo,hi])=>'<div class="cell band">'+(lo?lo+'–'+hi+'억':hi+'억 미만')+'<small>'+(lo?'이상 ~ 미만':'')+'</small></div>'+regions.map(r=>{let list=items.filter(a=>a.region===r&&latest(a).price>=lo&&latest(a).price<hi).sort((a,b)=>latest(a).price-latest(b).price);return'<div class="cell">'+(list.length?list.map(a=>'<button class="card" data-id="'+esc(a.id)+'"><span class="tag">'+esc(a.purpose||'목적 미정')+'</span><h3>'+esc(a.name)+'</h3><div class="meta">'+esc(a.address)+(a.listing?'<br>'+esc(a.listing.building+' · '+a.listing.floor):'')+'</div><div class="price">'+money(latest(a).price)+'</div><div class="meta">'+esc(a.kind)+'<br>기록 '+latest(a).date.replaceAll('-','.')+'</div></button>').join(''):'<div class="empty">'+(r==='광교'?'관심 아파트를 추가하세요':'등록된 아파트 없음')+'</div>')+'</div>'}).join('')).join('');board.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>openDetail(b.dataset.id))}
function openDetail(id){current=id;let a=data.find(a=>a.id===id),h=sorted(a),url=safeurl(a.url),delta=h.length>1?h.at(-1).price-h[0].price:null;$('detailcontent').innerHTML='<div class="paneltop"><span class="tag">'+esc(a.purpose||'목적 미정')+'</span><button class="close" id="closedetail" aria-label="닫기">✕</button></div><h2>'+esc(a.name)+'</h2><p style="margin:6px 0">'+esc(a.address)+'</p><div class="bigprice">'+money(latest(a).price)+'</div><div class="meta">'+esc(a.kind)+' · '+latest(a).date+' 확인'+(delta!==null?' · 최초 대비 '+(delta>0?'+':delta<0?'−':'')+money(Math.abs(delta)):'')+'</div><div class="detailgrid"><div><small>지역</small>'+esc(a.region)+'</div><div><small>전용면적</small>'+(a.area?a.area+'㎡'+(a.areaApprox?'대':''):'확인 필요')+'</div><div><small>최근 표시 실거래가</small>'+(a.trade?money(a.trade.price):'등록 전')+'</div><div><small>거래일 · 층</small>'+(a.trade?esc(a.trade.date+' · '+a.trade.floor):'등록 전')+'</div></div>'+(a.listing?'<h3>네이버에서 확인한 매물</h3><div class="note">'+esc(a.listing.building+' · '+a.listing.floor)+'<br>'+esc(a.listing.description)+'<br>비교용으로 선택한 매물 1건이며 단지 전체의 최저가나 평균가는 아닙니다.'+(a.areaApprox?'<br>면적은 네이버 요약 목록 표기이며 소수점 면적은 상세 매물에서 확인하세요.':'')+'</div>':'')+'<section id="market-history"></section>'+'<h3>검토 메모</h3><textarea id="editmemo" rows="3" style="width:100%" maxlength="2000">'+esc(a.memo)+'</textarea><div class="actions" style="margin-top:15px"><button id="savememo">메모 저장</button>'+(url?'<a style="padding:10px" href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">'+(a.listing?'네이버 단지 매물 목록':'출처 / 매물 보기')+'</a>':'')+'<button id="deleteitem" style="margin-left:auto;color:#9b4b4b">삭제</button></div>';$('closedetail').onclick=()=>$('detail').close();$('savememo').onclick=()=>{a.memo=$('editmemo').value;save();toast('메모를 저장했어요')};$('deleteitem').onclick=()=>{if(confirm(a.name+'을(를) 삭제할까요?')){data=data.filter(x=>x.id!==id);save();$('detail').close()}};window.renderMarketHistory?.(a);if(!$('detail').open)$('detail').showModal()}
$('search').oninput=render;$('add').onclick=()=>{$('form').reset();$('date').value=today();$('editor').showModal()};$('form').onsubmit=e=>{e.preventDefault();if($('url').value&&!safeurl($('url').value)){toast('http 또는 https 링크를 입력하세요');return}data.push({id:crypto.randomUUID(),name:$('name').value.trim(),region:$('region').value.trim(),purpose:$('purpose').value.trim(),address:$('address').value.trim(),area:Number($('area').value)||null,kind:$('kind').value,url:$('url').value,memo:$('memo').value,trade:null,history:[{date:$('date').value,price:Number($('amount').value),source:$('kind').value==='네이버 확인 호가'?'네이버부동산':'직접 입력'}]});save();$('editor').close();toast('아파트를 추가했어요')};$('export').onclick=()=>{let blob=new Blob([JSON.stringify({version:1,data},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='home-watch-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('import').onclick=()=>$('file').click();$('file').onchange=async e=>{try{let obj=JSON.parse(await e.target.files[0].text());if(obj.version!==1||!validBoard(obj.data))throw Error();if(confirm('현재 목록을 백업 파일의 '+obj.data.length+'개 아파트로 교체할까요?')){data=obj.data;save();toast('백업을 불러왔어요')}}catch{toast('올바른 트래커 백업 파일을 선택하세요')}e.target.value=''};[$('detail'),$('editor')].forEach(d=>d.addEventListener('click',e=>{if(e.target===d)d.close()}));render();

window.homeWatch={
 isValid:validBoard,
 getData:()=>structuredClone(data),
 getSeed:()=>structuredClone(seed),
 replaceData(next){data=structuredClone(next);localStorage.setItem(key,JSON.stringify(data));render()},
 switchUser(id){key=id?'hyokyung-home-watch-user-'+id:'hyokyung-home-watch-v1';let saved;try{saved=JSON.parse(localStorage.getItem(key))}catch{};data=validBoard(saved)?saved:structuredClone(seed);render()},
 notify:toast
};
